import re, zlib
data = open('advisor_proposal.pdf','rb').read()
out = []
for m in re.finditer(rb'stream\r?\n(.*?)endstream', data, re.S):
    try:
        out.append(zlib.decompress(m.group(1)).decode('latin-1'))
    except Exception:
        pass
text = ' '.join(out)
chunks = re.findall(r'\((?:[^()\\\\]|\\\\.)*\)', text)
print(' '.join(c[1:-1] for c in chunks))
