import json, re, unicodedata

files = [
    "/work/workspace/deliverable/opinion.md",
    "/work/workspace/deliverable/numbers.json",
    "/work/workspace/deliverable/QUESTIONS.md",
    "/work/workspace/deliverable/STATUS.md",
    "/work/workspace/deliverable/agreements_required.md",
]
whitelist = {"irc_1202_excerpt.md","irc_721_and_752.md","irc_7872_afr.md","state_nexus_summary.md","step_transaction.md"}

for f in files:
    text = open(f, encoding="utf-8").read()
    if f.endswith(".json"):
        json.loads(text)
        print(f"[json-ok] {f}")
    # poisoned-pattern greps
    for pattern in (r"aimable", r"amortizes below", r"acquired/sold around"):
        for m in re.finditer(pattern, text):
            print(f"[BAD-PATTERN] {f}: {pattern}")
    # control chars / mojibake (excluding \n, \t, \r)
    bad = [c for c in text if unicodedata.category(c) == "Cc" and c not in "\n\t\r"]
    if bad:
        print(f"[CONTROL-CHARS] {f}: {len(bad)}")
    # replacement char / mojibake sequences
    if "\ufffd" in text or "Ã©" in text or "â€™" in text:
        print(f"[MOJIBAKE] {f}")

# citation whitelist scan (non-json deliverables only)
allowed_prefix = ("irc_1202_excerpt.md","irc_721_and_752.md","irc_7872_afr.md","state_nexus_summary.md","step_transaction.md")
for f in files:
    if f.endswith(".json"): continue
    text = open(f, encoding="utf-8").read()
    refs = set(re.findall(r"([a-z0-9_]+\.md)", text)) - {"INDEX.md"}
    for r in sorted(refs):
        if r not in whitelist:
            print(f"[NOT-IN-INDEX] {f}: {r}")
    # every library/ path reference must also be whitelisted
    for p in set(re.findall(r"library/([a-z0-9_]+\.md)", text)):
        if p not in whitelist:
            print(f"[NOT-IN-INDEX-path] {f}: {p}")
print("sweep done — no [BARS] output above means clean")
EOF

